class Solution {
public:
    int numOfPairs(vector<string>& nums,string target){
        unordered_map<string,int>freq;for(const string& s:nums)++freq[s];
        int ans=0;for(int i=1;i<(int)target.size();++i){
            string a=target.substr(0,i),b=target.substr(i);
            ans+=freq[a]*(freq[b]-(a==b));
        }
        return ans;
    }
};
